    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nourriture%20et%20Boissons.ashx#&quot; title=&quot;Nourriture et Boissons&quot;&gt;Nourriture et Boissons&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Outils%20de%20comp%C3%A9tences.ashx#&quot; title=&quot;Outils de comp&#233;tences&quot;&gt;Outils de comp&#233;tences&lt;/a&gt;&lt;/li&gt;
