  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Il peut aussi s&#39;agir d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Poison-(Capacit&#233;).html&quot; title=&quot;Poison (Ext ou Sur)&quot;&gt;capacit&#233; de monstre&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Le poison est une substance qui interf&#232;re avec les fonctions physiques naturelles des cr&#233;atures vivantes, entra&#238;nant des l&#233;sions et la mort. En g&#233;n&#233;ral, il suffit d’utiliser une dose infime.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;background-color: #fff; float: right; padding: 0 0 12px 12px&quot;&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Application_du_poison_0&quot;&gt;Application du poison&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Doses_multiples_de_poison_1&quot;&gt;Doses multiples de poison&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Fabrication_du_poison_2&quot;&gt;Fabrication du poison&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Exemples_de_poisons_3&quot;&gt;Exemples de poisons&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Descriptions_des_poisons_4&quot;&gt;Descriptions des poisons&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;La cible d’un poison peut lui r&#233;sister en r&#233;ussissant un jet de sauvegarde. On peut ralentir ou soigner les effets du poison avec des sorts comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ralentissement-Du-Poison.html&quot; title=&quot;Ralentissement du poison&quot;&gt;ralentissement du poison&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Neutralisation-Du-Poison.html&quot; title=&quot;Neutralisation du poison&quot;&gt;neutralisation du poison&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;Les poisons sont r&#233;partis en quatre cat&#233;gories en fonction de la mani&#232;re dont ils atteignent la cible : contact, ingestion, inhalation ou blessure.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Blessure.&lt;/b&gt; Ces poisons agissent essentiellement lorsque certaines cr&#233;atures r&#233;ussissent une attaque ou par l’interm&#233;diaire d’armes enduites de la toxine. En g&#233;n&#233;ral, les poisons de blessure n’ont pas de &lt;i&gt;temps d’incubation&lt;/i&gt; et ont une &lt;i&gt;fr&#233;quence&lt;/i&gt; de 1 minute.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contact.&lt;/b&gt; Ces poisons agissent au moment o&#249; ils entrent en contact avec la peau de la cr&#233;ature. Ils s’utilisent aussi comme des poisons de blessure. Les poisons de contact ont g&#233;n&#233;ralement un &lt;i&gt;temps d’incubation&lt;/i&gt; de 1 minute et une &lt;i&gt;fr&#233;quence&lt;/i&gt; de 1 minute.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ingestion.&lt;/b&gt; Ces poisons agissent au moment o&#249; la cr&#233;ature les ing&#232;re ou les boit. Les poisons d’ingestion ont g&#233;n&#233;ralement un &lt;i&gt;temps d’incubation&lt;/i&gt; de 10 minutes et une &lt;i&gt;fr&#233;quence&lt;/i&gt; de 1 minute.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Inhalation.&lt;/b&gt; Ces poisons agissent au moment o&#249; la cr&#233;ature p&#233;n&#232;tre dans une zone contamin&#233;e et, en g&#233;n&#233;ral, n’ont pas de temps d’incubation. Pour la plupart des poisons inhal&#233;s, 1 dose permet de remplir un cube de 3 m&#232;tres de c&#244;t&#233;. La cr&#233;ature peut tenter de retenir son souffle lorsqu’elle est dans la zone, pour &#233;viter de respirer la toxine. Une cr&#233;ature retenant son souffle a 50% de chances de ne pas avoir &#224; faire de jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; tous les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Reportez-vous aux r&#232;gles concernant le fait de &lt;a class=&quot;pagelink&quot; href=&quot;Dangers-Naturels.html#ASPHYXIE&quot; title=&quot;Les dangers naturels&quot;&gt;retenir son souffle&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Dangers-Naturels.html#ASPHYXIE&quot; title=&quot;Les dangers naturels&quot;&gt;suffocation&lt;/a&gt;. Si une cr&#233;ature retient son souffle et rate un test de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; pour continuer, plut&#244;t que de suffoquer, elle reprend son souffle normalement (et subit les effets du poison inhal&#233; s’il emplit toujours la zone).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Application du poison&lt;a class=&quot;headeranchor&quot; id=&quot;Application_du_poison_0&quot; href=&quot;#Application_du_poison_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une dose de poison appliqu&#233;e sur une arme ou sur un autre objet n’affecte qu’une seule cible. Une arme ou un objet empoisonn&#233; conserve le poison jusqu’&#224; ce que l’arme touche une cible ou jusqu’&#224; ce que l’objet soit touch&#233; (&#224; moins que le poison ne soit nettoy&#233; avant que la cible n’entre en contact avec). L’application de poison sur une arme ou sur une munition co&#251;te une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;. Que le personnage applique ou pr&#233;pare le poison pour utilisation, il a 5% de chances de s’y exposer et doit r&#233;ussir un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; normal contre le poison. Ceci ne consomme pas la dose de poison. Lorsque le personnage attaque avec une arme empoisonn&#233;e, il s’expose lui-m&#234;me au poison s’il fait un 1 naturel &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt;. Ceci consomme le poison de l’arme. Si le personnage a la capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#UTILISATIONDUPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;utilisation des poisons&lt;/a&gt; (issue, par exemple, de la classe de prestige &lt;a class=&quot;pagelink&quot; href=&quot;Assassin.html&quot; title=&quot;L&amp;#39;assassin&quot;&gt;assassin&lt;/a&gt; ou de la classe de base &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt;), il ne risque pas de s’empoisonner accidentellement lorsqu’il applique le poison sur une arme.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Doses multiples de poison&lt;a class=&quot;headeranchor&quot; id=&quot;Doses_multiples_de_poison_1&quot; href=&quot;#Doses_multiples_de_poison_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Contrairement aux autres afflictions, les poisons &#171; cumulent &#187; leurs effets, ce qui signifie que l’application de plusieurs doses d’un m&#234;me poison augmente son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; et sa dur&#233;e. Si la victime r&#233;ussit son premier &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; contre un poison, ses effets ne se cumulent pas : le poison n’affecte pas le personnage et toutes les autres doses sont trait&#233;es ind&#233;pendamment. De m&#234;me, si un poison a &#233;t&#233; neutralis&#233; ou s’il ne fait plus effet (que ce soit parce que le personnage a r&#233;ussi ses jets de sauvegarde ou s’il a surv&#233;cu &#224; sa dur&#233;e du poison), les effets ne se cumulent pas. N&#233;anmoins, s’il y a encore du poison actif dans l’organisme du personnage au moment o&#249; il est de nouveau affect&#233; par le m&#234;me poison, les effets se cumulent s’il rate son premier &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; contre la nouvelle dose. Ceci a deux effets qui durent jusqu’&#224; ce que les poisons se dissipent.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e augment&#233;e.&lt;/b&gt; Augmentez la dur&#233;e du poison de la moiti&#233; de la &lt;i&gt;fr&#233;quence&lt;/i&gt; indiqu&#233;e.&lt;/li&gt;&lt;li&gt;&lt;b&gt;DD augment&#233;.&lt;/b&gt; Augmentez le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du poison de +2.&lt;br /&gt;Ces augmentations sont cumulables (une troisi&#232;me dose rajoute la moiti&#233; de la &lt;i&gt;fr&#233;quence&lt;/i&gt; &#224; la dur&#233;e et encore +2 au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; etc.) Lorsque le personnage est affect&#233; par plusieurs doses d’un m&#234;me poison, il ne fait qu’un seul &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; contre le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; le plus &#233;lev&#233; &#224; chaque fois que l’exige la &lt;i&gt;fr&#233;quence&lt;/i&gt; indiqu&#233;e et non un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; pour chaque dose de poison.  &lt;br /&gt;Les multiples doses de poison n’alt&#232;rent pas la condition de &lt;i&gt;gu&#233;rison&lt;/i&gt; du poison. Si elle est remplie, elle neutralise toutes les doses re&#231;ues.  &lt;br /&gt;Les poisons de contact et de blessure infligent seulement une dose de poison par arme (le poison de l’arme disparaissant apr&#232;s la premi&#232;re attaque r&#233;ussie). Les poisons inhal&#233;s et ing&#233;r&#233;s peuvent infliger les effets de plusieurs doses &#224; la fois.&lt;br /&gt;Les doses de poisons diff&#233;rents (si un &lt;a class=&quot;pagelink&quot; href=&quot;Assassin.html&quot; title=&quot;L&amp;#39;assassin&quot;&gt;assassin&lt;/a&gt; combine l’extrait de sanvert de sa dague avec le venin d’araign&#233;e de taille M de son &#233;p&#233;e courte) ne se cumulent pas : les effets de chacun sont trait&#233;s ind&#233;pendamment.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Exemples.&lt;/b&gt; Un guerrier fait face &#224; trois araign&#233;es de taille M (qui inoculent du venin d’araign&#233;e de taille M sur une morsure r&#233;ussie). Le venin de l’araign&#233;e de taille M a normalement une &lt;i&gt;fr&#233;quence&lt;/i&gt; de 4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; et un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de 14. Lors du premier &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, les trois araign&#233;es mordent le guerrier qui rate ses trois &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt;. Les deuxi&#232;me et troisi&#232;me doses augmentent chacune la dur&#233;e totale du poison de 2 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; (la moiti&#233; des 4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; de &lt;i&gt;fr&#233;quence&lt;/i&gt;) et son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de +2, pour une dur&#233;e totale de 8 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; (4+2+2) et un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de 18 (14+2+2). Heureusement, le venin d’araign&#233;e de taille M se soigne avec un seul &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; r&#233;ussi, m&#234;me si le guerrier lutte contre trois doses &#224; la fois.&lt;br /&gt;Cette fois, le guerrier r&#233;ussit deux de ses premiers &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre le venin d’araign&#233;e : il n’a donc qu’une dose de poison dans l’organisme. Il rate son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; lors de son tour. Au tour des araign&#233;es, deux d’entre elles le mordent et il rate ses deux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt;, ce qui fait passer la dur&#233;e du poison &#224; 8 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; et son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; &#224; 18, comme s’il avait rat&#233; ses trois jets dans le m&#234;me &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Fabrication du poison&lt;a class=&quot;headeranchor&quot; id=&quot;Fabrication_du_poison_2&quot; href=&quot;#Fabrication_du_poison_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le personnage ayant la comp&#233;tence &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (alchimie) peut fabriquer du poison. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de fabrication d’un poison est &#233;gal au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de son jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt;. S’il fait un 1 naturel &#224; son test d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; pour fabriquer un poison, le personnage s’expose au poison. Ceci ne consomme pas la dose. S’il a la capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#UTILISATIONDUPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;utilisation des poisons&lt;/a&gt;, le personnage ne risque pas de s’empoisonner accidentellement lorsqu’il fabrique du poison.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Exemples de poisons&lt;a class=&quot;headeranchor&quot; id=&quot;Exemples_de_poisons_3&quot; href=&quot;#Exemples_de_poisons_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les exemples de poisons pr&#233;sent&#233;s ci-dessous ne constituent qu’une partie des poisons les plus courants que l’on trouve en ville. Bien entendu, la plupart des villes ont leurs propres lois concernant l’achat, la vente ou la fabrication du poison. Pour plus d&#39;informations sur le format des descriptions, voir &lt;a class=&quot;pagelink&quot; href=&quot;Afflictions.html&quot; title=&quot;Les afflictions&quot;&gt;les afflictions&lt;/a&gt;. Sauf indication contraire, les modifications de caract&#233;ristiques sont des &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement temporaire&quot;&gt;affaiblissements temporaires&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt&quot; WIDTH=&quot;100%&quot;&gt;&lt;caption&gt;Exemples de poisons&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TABLEAUPOISONS&quot; href=&quot;#TABLEAUPOISONS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;Type&lt;/td&gt;&lt;td&gt;DD Vig&lt;/td&gt;&lt;td&gt;Incubation&lt;/td&gt;&lt;td&gt;Fr&#233;quence&lt;/td&gt;&lt;td&gt;Effet&lt;/td&gt;&lt;td&gt;Co&#251;t&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Ajonc &#224; feuilles bleues&quot; title=&quot;Les poisons  &quot;&gt;Ajonc &#224; feuilles bleues&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Blessure&lt;/td&gt;&lt;td&gt;14&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;1/rd pdt 2 rds&lt;/td&gt;&lt;td&gt;1 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Con&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;Inconscience&lt;/a&gt; 1d3 h&lt;/td&gt;&lt;td&gt;120 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Bavededhabba&quot; title=&quot;Les poisons  &quot;&gt;Bave de dhabba&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Blessure&lt;/td&gt;&lt;td&gt;12&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;1d6 d&#233;g&#226;ts d’acide, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Naus&#233;eux.html&quot; title=&quot;Naus&#233;eux&quot;&gt;naus&#233;e&lt;/a&gt;/1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;Dex&quot;&gt;Dex&lt;/a&gt;&lt;/td&gt;&lt;td&gt;50 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Br&#251;le-sorts&quot; title=&quot;Les poisons  &quot;&gt;Br&#251;le-sorts&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Blessure&lt;/td&gt;&lt;td&gt;14&lt;/td&gt;&lt;td&gt;–&lt;/td&gt;&lt;td&gt;1/rd pdt 4 rds&lt;/td&gt;&lt;td&gt;&lt;abbr title=&quot;La cible doit r&#233;ussir un test de concentration DD 10 + niveau du sort pour parvenir &#224; lancer un sort, et subit un malus de -5 &#224; tous ses autres tests de concentration.&quot;&gt;voir texte&lt;/abbr&gt;&lt;/td&gt;&lt;td&gt;200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Essencedombre&quot; title=&quot;Les poisons  &quot;&gt;Essence d’ombre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Blessure&lt;/td&gt;&lt;td&gt;17&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;1/rd pdt 6 rds&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;diminution permanente&quot;&gt;Dim&lt;/a&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;For&lt;/a&gt;/1d2 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;For&lt;/a&gt;&lt;/td&gt;&lt;td&gt;250 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Extraitdesanvert&quot; title=&quot;Les poisons  &quot;&gt;Extrait de sanvert&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Blessure&lt;/td&gt;&lt;td&gt;13&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;1/rd pdt 4 rds&lt;/td&gt;&lt;td&gt;1 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Con&lt;/a&gt;&lt;/td&gt;&lt;td&gt;100 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Mortelame&quot; title=&quot;Les poisons  &quot;&gt;Mortelame&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Blessure&lt;/td&gt;&lt;td&gt;20&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;1/rd pdt 6 rds&lt;/td&gt;&lt;td&gt;1d3 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Con&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Poisondaraign&#233;enoiredesmarais&quot; title=&quot;Les poisons  &quot;&gt;Poison d&#39;araign&#233;e noire des marais&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Blessure&lt;/td&gt;&lt;td&gt;14&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;1/rd pdt 6 rds&lt;/td&gt;&lt;td&gt;1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dex&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Confus.html&quot; title=&quot;Confus&quot;&gt;confusion&lt;/a&gt; 1 rd&lt;/td&gt;&lt;td&gt;800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Poisondevouivre&quot; title=&quot;Les poisons  &quot;&gt;Poison de vouivre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Blessure&lt;/td&gt;&lt;td&gt;17&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;1/rd pdt 6 rds&lt;/td&gt;&lt;td&gt;1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Con&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#Poisondrow&quot; title=&quot;Les poisons  &quot;&gt;Poison drow&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Blessure&lt;/td&gt;&lt;td&gt;13&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;1/min pdt 2 min&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;Inconscience&lt;/a&gt; 1 min/2d4 h&lt;/td&gt;&lt;td&gt;75 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quo